package octal

import "errors"

// ParseOctal converts an octal number represented as a string (e.g. "1735263")
// to its decimal equivalent, computed from first principles.
// Invalid input (any character outside 0-7) yields 0 and an error.
func ParseOctal(input string) (int64, error) {
	var result int64
	for _, c := range input {
		if c < '0' || c > '7' {
			return 0, errors.New("invalid octal digit: " + string(c))
		}
		// Horner's method: accumulate value*8 + digit, equivalent to
		// summing each digit times its power of 8.
		result = result*8 + int64(c-'0')
	}
	return result, nil
}
